        public IActionResult EditCartTemplate(int id)
        {
            var cardTemplate = _context.CardTemplates.Where(e => e.CardTemplateId == id).FirstOrDefault();
            if (cardTemplate == null)
            {
                return NotFound();
            }
            ViewBag.ImageServer = _context.ImageServers.ToList();
            return View(cardTemplate);
        }
        [HttpPost]
        [ValidateAntiForgeryToken]
        public IActionResult EditCartTemplate(int id, [Bind("CardTemplateId,Title,MoTa,HtmlContent,Type,CreatedAt,DateModified")] CardTemplate cardTemplate)
        {
            if (id != cardTemplate.CardTemplateId)
            {
                return NotFound();
            }
            if (ModelState.IsValid)
            {
                try
                {
                    cardTemplate.DateModified = DateTime.Now;
                    _context.CardTemplates.Update(cardTemplate);
                    _context.SaveChanges();
                }
                catch (DbUpdateConcurrencyException)
                {
                    
                }
                return RedirectToAction("EditCartTemplate", new { id = cardTemplate.CardTemplateId });
            }
            return View(cardTemplate);
        }
